#!/usr/bin/env bun
import { existsSync, renameSync, writeFileSync, readFileSync } from "fs";
import { resolve, dirname, join } from "path";

interface Task {
  id: number;
  title: string;
  status: "open" | "done";
  createdAt: string;
  completedAt?: string;
  tags?: string[];
  due?: string;
}

interface DB {
  nextId: number;
  tasks: Task[];
}

function dbPath(): string {
  const f = process.env.TASKBOARD_FILE;
  return resolve(f && f.length > 0 ? f : ".taskboard.json");
}

function fail(msg: string): never {
  console.error(msg);
  process.exit(1);
}

function loadDB(): DB {
  const p = dbPath();
  if (!existsSync(p)) {
    return { nextId: 1, tasks: [] };
  }
  let raw: string;
  try {
    raw = readFileSync(p, "utf8");
  } catch (e) {
    fail(`error: cannot read database: ${(e as Error).message}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    fail(`error: malformed database: ${(e as Error).message}`);
  }
  if (
    typeof parsed !== "object" ||
    parsed === null ||
    !Array.isArray((parsed as DB).tasks) ||
    typeof (parsed as DB).nextId !== "number"
  ) {
    fail("error: malformed database: invalid structure");
  }
  return parsed as DB;
}

function saveDB(db: DB): void {
  const p = dbPath();
  const dir = dirname(p);
  const tmp = join(dir, `.taskboard.tmp.${process.pid}.${Date.now()}.json`);
  writeFileSync(tmp, JSON.stringify(db, null, 2));
  renameSync(tmp, p);
}

function isValidDate(s: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const [y, m, d] = s.split("-").map(Number);
  const dt = new Date(y, m - 1, d);
  return (
    dt.getFullYear() === y &&
    dt.getMonth() === m - 1 &&
    dt.getDate() === d
  );
}

function todayLocal(): string {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, "0");
  const d = String(now.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function parseTags(s: string | undefined): string[] | undefined {
  if (s === undefined) return undefined;
  const seen = new Set<string>();
  const out: string[] = [];
  for (const raw of s.split(",")) {
    const t = raw.trim().toLowerCase();
    if (t.length === 0) continue;
    if (seen.has(t)) continue;
    seen.add(t);
    out.push(t);
  }
  return out;
}

function out(value: unknown): void {
  console.log(JSON.stringify(value));
}

function usage(): never {
  fail(
    "usage: bun run src/cli.ts <add|list|done|delete|stats> [args]"
  );
}

function cmdAdd(args: string[]): void {
  let title: string | undefined;
  let tagsRaw: string | undefined;
  let due: string | undefined;
  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === "--title") {
      title = args[++i];
    } else if (a === "--tags") {
      tagsRaw = args[++i];
    } else if (a === "--due") {
      due = args[++i];
    } else {
      fail(`error: unknown flag: ${a}`);
    }
  }
  if (title === undefined || title.length === 0) {
    fail("error: --title is required and must be non-empty");
  }
  if (due !== undefined && !isValidDate(due)) {
    fail(`error: invalid due date: ${due}`);
  }
  const db = loadDB();
  const task: Task = {
    id: db.nextId,
    title,
    status: "open",
    createdAt: new Date().toISOString(),
  };
  const tags = parseTags(tagsRaw);
  if (tags !== undefined) task.tags = tags;
  if (due !== undefined) task.due = due;
  db.tasks.push(task);
  db.nextId += 1;
  saveDB(db);
  out(task);
}

function cmdList(args: string[]): void {
  let status: string | undefined;
  let tag: string | undefined;
  let overdue: string | undefined;
  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === "--status") {
      status = args[++i];
    } else if (a === "--tag") {
      tag = args[++i];
    } else if (a === "--overdue") {
      overdue = args[++i];
    } else {
      fail(`error: unknown flag: ${a}`);
    }
  }
  if (status !== undefined && status !== "open" && status !== "done") {
    fail(`error: invalid status: ${status}`);
  }
  if (overdue !== undefined && !isValidDate(overdue)) {
    fail(`error: invalid overdue date: ${overdue}`);
  }
  const db = loadDB();
  let tasks = db.tasks.slice();
  if (status !== undefined) {
    tasks = tasks.filter((t) => t.status === status);
  }
  if (tag !== undefined) {
    const norm = tag.trim().toLowerCase();
    tasks = tasks.filter((t) => (t.tags || []).includes(norm));
  }
  if (overdue !== undefined) {
    tasks = tasks.filter(
      (t) => t.status === "open" && t.due !== undefined && t.due < overdue
    );
  }
  tasks.sort((a, b) => a.id - b.id);
  out(tasks);
}

function findTask(db: DB, id: number): Task {
  const t = db.tasks.find((x) => x.id === id);
  if (!t) fail(`error: task not found: ${id}`);
  return t;
}

function cmdDone(args: string[]): void {
  if (args.length !== 1) fail("usage: bun run src/cli.ts done ID");
  const id = Number(args[0]);
  if (!Number.isInteger(id)) fail(`error: invalid id: ${args[0]}`);
  const db = loadDB();
  const t = findTask(db, id);
  if (t.status === "done") {
    out(t);
    return;
  }
  t.status = "done";
  t.completedAt = new Date().toISOString();
  saveDB(db);
  out(t);
}

function cmdDelete(args: string[]): void {
  if (args.length !== 1) fail("usage: bun run src/cli.ts delete ID");
  const id = Number(args[0]);
  if (!Number.isInteger(id)) fail(`error: invalid id: ${args[0]}`);
  const db = loadDB();
  const idx = db.tasks.findIndex((x) => x.id === id);
  if (idx === -1) fail(`error: task not found: ${id}`);
  const [removed] = db.tasks.splice(idx, 1);
  saveDB(db);
  out(removed);
}

function cmdStats(): void {
  const db = loadDB();
  const today = todayLocal();
  let open = 0;
  let done = 0;
  let overdue = 0;
  for (const t of db.tasks) {
    if (t.status === "done") {
      done++;
    } else {
      open++;
      if (t.due !== undefined && t.due < today) overdue++;
    }
  }
  out({ total: db.tasks.length, open, done, overdue });
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length === 0) usage();
  const cmd = args[0];
  const rest = args.slice(1);
  switch (cmd) {
    case "add":
      cmdAdd(rest);
      break;
    case "list":
      cmdList(rest);
      break;
    case "done":
      cmdDone(rest);
      break;
    case "delete":
      cmdDelete(rest);
      break;
    case "stats":
      if (rest.length > 0) fail(`error: stats takes no arguments`);
      cmdStats();
      break;
    default:
      usage();
  }
}

main();

